The files need to define the standard grade-school roster API:

- `add` stores a student only once across the entire school.
- `grade` returns students in the requested grade, alphabetically sorted.
- `roster` returns all grades with alphabetically sorted students.
- Grades are naturally ordered using `std::map`.

grade_school.h
```
#if !defined(GRADE_SCHOOL_H)
#define GRADE_SCHOOL_H

#include <map>
#include <string>
#include <vector>

namespace grade_school {

class school {
public:
    void add(int grade, const std::string& student);
    std::vector<std::string> grade(int grade) const;
    std::map<int, std::vector<std::string>> roster() const;

private:
    std::map<int, std::vector<std::string>> students_;
};

}  // namespace grade_school

#endif  // GRADE_SCHOOL_H
```

grade_school.cpp
```
#include "grade_school.h"

#include <algorithm>

namespace grade_school {

void school::add(int grade_number, const std::string& student_name)
{
    for (const auto& [current_grade, students] : students_) {
        if (std::find(students.begin(), students.end(), student_name) != students.end()) {
            return;
        }
    }

    students_[grade_number].push_back(student_name);
    std::sort(students_[grade_number].begin(), students_[grade_number].end());
}

std::vector<std::string> school::grade(int grade_number) const
{
    const auto found_grade = students_.find(grade_number);

    if (found_grade == students_.end()) {
        return {};
    }

    return found_grade->second;
}

std::map<int, std::vector<std::string>> school::roster() const
{
    return students_;
}

}  // namespace grade_school
